-- ============================================================================
-- Create the Foster Application form (Forminator) on the LIVE site + a page
-- Site: bubblespetrescue.ae   |  Table prefix assumed: wpqx_
--
-- Your live site has no foster form yet, so this CREATES a new one (the
-- database assigns its ID automatically, so nothing can collide). Content is
-- matched field-for-field to the Foster Word document; notifications go to
-- LittleAngelsUAE@outlook.com.
--
-- BEFORE YOU RUN THIS
--   1. BACK UP FIRST: phpMyAdmin > pick your DB > Export > Go.
--   2. Confirm the table prefix is "wpqx_" (else change it below).
--
-- HOW TO RUN
--   phpMyAdmin > your DB > "SQL" tab > paste all of this > Go.
-- ============================================================================

START TRANSACTION;

-- ---- PART 1: create the form (required) -----------------------------------
INSERT INTO `wpqx_posts`
  (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,
   `post_status`,`comment_status`,`ping_status`,`post_password`,`post_name`,`to_ping`,`pinged`,
   `post_modified`,`post_modified_gmt`,`post_content_filtered`,`post_parent`,`guid`,`menu_order`,
   `post_type`,`post_mime_type`,`comment_count`)
VALUES
  (1, NOW(), UTC_TIMESTAMP(), '', 'Foster Application - Bubbles Pets Rescue', '',
   'publish','closed','closed','', 'foster-application-bubbles-pets-rescue','','',
   NOW(), UTC_TIMESTAMP(), '', 0, '', 0,
   'forminator_forms','',0);

SET @form_id = LAST_INSERT_ID();

UPDATE `wpqx_posts`
   SET `guid` = CONCAT('https://www.bubblespetrescue.ae/?post_type=forminator_forms&p=', @form_id)
 WHERE `ID` = @form_id;

INSERT INTO `wpqx_postmeta` (`post_id`,`meta_key`,`meta_value`)
VALUES (@form_id, 'forminator_form_meta', 'a:4:{s:6:"fields";a:26:{i:0;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736564-7230";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-1";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:671:"<p>Thank you for opening your home and heart to one of our rescued animals.</p><p>Fostering gives a rescued pet the chance to experience a loving home environment rather than spending time in a kennel or boarding facility. It also helps us open up space for other animals in need of rescue and care.</p><p>Please take your time to answer the following questions carefully. Fostering is a meaningful responsibility that requires commitment, patience, and teamwork and we\'re here to support you every step of the way.</p><p>&#128231; Email: LittleAngelsUAE@outlook.com<br/>&#128241; WhatsApp: +971 50 808 3083<br/>&#128248; Instagram &amp; Facebook: @Bubbles.PetsRescue</p>";}}}i:1;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736564-9876";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:6:"text-1";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:49:"Name of the rescue you are applying to foster for";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:2;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736564-4495";s:6:"fields";a:1:{i:0;a:6:{s:10:"element_id";s:9:"section-1";s:4:"type";s:7:"section";s:4:"cols";s:2:"12";s:13:"section_title";s:28:"Foster Applicant Information";s:16:"section_subtitle";s:0:"";s:14:"section_border";s:4:"none";}}}i:3;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736564-9453";s:6:"fields";a:1:{i:0;a:7:{s:10:"element_id";s:6:"text-2";s:4:"type";s:4:"text";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:9:"Full name";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:4;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736564-4742";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:10:"textarea-1";s:4:"type";s:8:"textarea";s: