s:10:"opt-314556";}i:1;a:4:{s:5:"label";s:2:"No";s:5:"value";s:2:"no";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-496542";}}}}}i:17;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-2727";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:10:"textarea-4";s:4:"type";s:8:"textarea";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:114:"Are you a first-time owner or a first-time foster parent? Please share details about your experience with animals.";s:11:"placeholder";s:0:"";s:10:"input_type";s:9:"paragraph";s:10:"limit_type";s:10:"characters";s:14:"default_editor";s:5:"false";}}}i:18;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-4896";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:7:"radio-7";s:4:"type";s:5:"radio";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:99:"Do you have a car, and are you comfortable doing the pickup and drop-off for fostering when needed?";s:11:"placeholder";s:0:"";s:10:"value_type";s:5:"radio";s:6:"layout";s:6:"inline";s:7:"options";a:2:{i:0;a:4:{s:5:"label";s:3:"Yes";s:5:"value";s:3:"yes";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-856848";}i:1;a:4:{s:5:"label";s:2:"No";s:5:"value";s:2:"no";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-923351";}}}}}i:19;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-1146";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:7:"radio-8";s:4:"type";s:5:"radio";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:162:"Would you consider adopting your foster animal if the experience goes well? (Note: there\'s an adoption form to fill later, and standard adoption fees will apply.)";s:11:"placeholder";s:0:"";s:10:"value_type";s:5:"radio";s:6:"layout";s:6:"inline";s:7:"options";a:3:{i:0;a:4:{s:5:"label";s:3:"Yes";s:5:"value";s:3:"yes";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-497990";}i:1;a:4:{s:5:"label";s:2:"No";s:5:"value";s:2:"no";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-811958";}i:2;a:4:{s:5:"label";s:5:"Maybe";s:5:"value";s:5:"maybe";s:5:"limit";s:0:"";s:3:"key";s:10:"opt-593279";}}}}}i:20;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-6959";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-2";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:4383:"<h3>&#128062; Foster Agreement &amp; Responsibilities</h3><p>As a valued foster parent with Bubbles Pets Rescue, we want you to know that we are here to make your experience simple, supported, and rewarding. By submitting this form, you acknowledge that you understand and agree to the following guidelines:</p><p><strong>1. Animal safety and responsibility</strong><br/>Foster animals remain under the legal care and ownership of Bubbles Pets Rescue at all times. Each rescue animal is microchipped and registered under the organization. You are advised not to rehome, hand over, or transfer the foster animal to anyone, including friends, family, or other fosters, without first informing and receiving approval from the rescue. If a foster parent goes out of contact or transfers the animal without communication, the rescue will take legal action and reclaim the animal through the appropriate authorities.</p><p><strong>2. Regular communication</strong><br/>We kindly ask all fosters to send weekly photos and short videos of their foster animal. These updates are used to maintain the animal\'s adoption profile and to help us find them a permanent home faster.</p><p><strong>3. Adoption process</strong><br/>Once a rescue moves into your care, Bubbles Pets Rescue will continue promoting them for adoption. Updates, photos, and progress stories may be shared publicly on our social media pages. If an adopter is selected, we will reach out to coordinate a meeting or collection with you directly.</p><p><strong>4. Helping us find homes</strong><br/>You are more than welcome to share your foster\'s story, photos, and updates with your own network to help find potential adopters, and we are grateful for your support with this. However, anyone interested in adopting must contact Bubbles Pets Rescue directly via WhatsApp to continue through the official adoption process.</p><p><strong>5. Traveling or change of circumstances</strong><br/>If you experience any changes, such as travel plans, a change of mind, or personal situations, please don\'t worry. We will always take full responsibility for the rescue and arrange their next steps safely. We simply ask that you inform us as early as possible (ideally with at least one week\'s notice) so that we can prepare accordingly. If you are traveling during your foster period, please reach out so we can discuss the best solution together.</p><p><strong>6. Health and veterinary care</strong><br/>All foster animals come healthy, vaccinated, spayed/neutered, and cleared from isolation, unless you have agreed to foster one under medical care. Should any veterinary care be needed during fostering, please contact us immediately. Bubbles Pets Rescue will handle all coordination and cover approved medical costs through our partner clinic. We kindly expect foster parents to provide attentive care and maintain the animal\'s well-being throughout the foster period, and to return animals to us in good health, not in a worsened condition.</p><p><strong>7. Food and supplies</strong><br/>We do our best to provide food and basic items depending on donations and stock availability. In times when supplies are limited, we appreciate your help in arranging food or essentials for your foster pet.</p><p><strong>8. Support and guidance</strong><br/>You\'ll always have our full support. Our team is just a WhatsApp message away for any questions, concerns, or advice, from the moment your foster arrives until they find their forever home.</p><p><strong>9. Commitment and honesty</strong><br/>All information shared in this form is confirmed to be true and complete. Fostering is a temporary but vital step that helps rescued animals transition to a permanent, loving home.</p><p><strong>10. Adoption of your foster pet</strong><br/>We absolutely love "foster fails", when a foster parent falls in love and decides to give their rescue a forever home. If you decide to adopt your foster pet during your foster period, please inform Bubbles Pets Rescue as soon as possible. Since we continuously promote our rescues for adoption, it\'s important that we know your decision before another adoption is confirmed. In this case, you\'ll be asked to complete our Adoption Application Form, and the standard adoption fee will apply. We\'ll then discuss and finalize everything together to make it official, turning your foster into family.</p>";}}}i:21;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-6314";s:6:"fields";a:1:{i:0;a:8:{s:10:"element_id";s:9:"consent-1";s:4:"type";s:7:"consent";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:0:"";s:11:"placeholder";s:0:"";s:19:"consent_description";s:167:"I have read, understood, and agree to the Foster Agreement &amp; Responsibilities above, and I confirm that all information provided in this form is true and complete.";s:12:"consent_type";s:8:"checkbox";}}}i:22;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-6710";s:6:"fields";a:2:{i:0;a:7:{s:10:"element_id";s:6:"text-6";s:4:"type";s:4:"text";s:4:"cols";s:1:"6";s:8:"required";b:1;s:11:"field_label";s:21:"Name of foster animal";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}i:1;a:7:{s:10:"element_id";s:6:"text-7";s:4:"type";s:4:"text";s:4:"cols";s:1:"6";s:8:"required";b:1;s:11:"field_label";s:18:"Emirates ID number";s:11:"placeholder";s:0:"";s:10:"limit_type";s:10:"characters";}}}i:23;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-6869";s:6:"fields";a:1:{i:0;a:9:{s:10:"element_id";s:11:"signature-1";s:4:"type";s:9:"signature";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:19:"Applicant signature";s:11:"placeholder";s:0:"";s:4:"icon";s:4:"true";s:6:"height";s:3:"150";s:9:"thickness";s:1:"2";}}}i:24;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-5368";s:6:"fields";a:1:{i:0;a:14:{s:10:"element_id";s:6:"date-1";s:4:"type";s:4:"date";s:4:"cols";s:2:"12";s:8:"required";b:1;s:11:"field_label";s:4:"Date";s:11:"placeholder";s:0:"";s:10:"field_type";s:6:"picker";s:11:"date_format";s:8:"dd/mm/yy";s:4:"icon";s:4:"true";s:12:"default_date";s:4:"none";s:10:"start_year";s:0:"";s:8:"end_year";s:0:"";s:17:"start_offset_type";s:1:"+";s:15:"end_offset_type";s:1:"+";}}}i:25;a:2:{s:10:"wrapper_id";s:26:"wrapper-1784648736565-8348";s:6:"fields";a:1:{i:0;a:5:{s:10:"element_id";s:6:"html-3";s:4:"type";s:4:"html";s:4:"cols";s:2:"12";s:11:"field_label";s:0:"";s:10:"variations";s:373:"<h3>&#128204; Important Note</h3><p>Please notify us once you\'ve completed this form. As a small volunteer-run rescue, we manage many aspects of animal care and may not respond immediately, but you\'re always welcome to follow up about your application. We truly appreciate your kindness, time, and compassion in helping us give our rescues a second chance at happiness.</p>";}}}}s:8:"settings";a:27:{s:8:"formName";s:40:"Foster Application - Bubbles Pets Rescue";s:7:"version";s:3:"1.0";s:17:"pagination-header";s:3:"nav";s:26:"cform-section-border-color";s:7:"#E9E9E9";s:11:"form-expire";s:9:"no_expire";s:17:"form-border-style";s:4:"none";s:12:"form-padding";s:0:"";s:11:"form-border";s:0:"";s:12:"fields-style";s:4:"open";s:16:"field-image-size";s:6:"custom";s:10:"validation";s:9:"on_submit";s:17:"validation-inline";b:1;s:18:"akismet-protection";s:4:"true";s:10:"form-style";s:7:"default";s:13:"form-substyle";s:7:"default";s:11:"enable-ajax";s:4:"true";s:9:"autoclose";s:4:"true";s:20:"submission-indicator";s:4:"show";s:15:"indicator-label";s:15:"Submitting form";s:14:"paginationData";a:2:{s:24:"pagination-header-design";s:4:"show";s:17:"pagination-header";s:3:"nav";}s:10:"submitData";a:2:{s:18:"custom-submit-text";s:25:"Submit Foster Application";s:27:"custom-invalid-form-message";s:58:"Error: Please review the highlighted fields and try again.";}s:22:"enable-fraud-detection";s:4:"true";