-- this PART 2 block before running. If a page with slug 'foster-application'
-- already exists, skip Part 2 to avoid a duplicate.
INSERT INTO `wpqx_posts`
  (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,
   `post_status`,`comment_status`,`ping_status`,`post_password`,`post_name`,`to_ping`,`pinged`,
   `post_modified`,`post_modified_gmt`,`post_content_filtered`,`post_parent`,`guid`,`menu_order`,
   `post_type`,`post_mime_type`,`comment_count`)
VALUES
  (1, NOW(), UTC_TIMESTAMP(),
   CONCAT('<!-- wp:shortcode -->[forminator_form id="', @form_id, '"]<!-- /wp:shortcode -->'),
   'Foster Application', '',
   'publish','closed','closed','', 'foster-application','','',
   NOW(), UTC_TIMESTAMP(), '', 0, '', 0,
   'page','',0);

SET @page_id = LAST_INSERT_ID();
UPDATE `wpqx_posts`
   SET `guid` = CONCAT('https://www.bubblespetrescue.ae/?page_id=', @page_id)
 WHERE `ID` = @page_id;

COMMIT;

-- After running: Forminator > Forms shows "Foster Application", and
-- Pages shows a published "Foster Application" page at /foster-application.
-- Add it to your menu via Appearance > Menus.
